import{_ as a,o as i,c as t,a0 as e}from"./chunks/framework.Lyg3o82c.js";const k=JSON.parse('{"title":"安装","description":"了解如何创建新的 AdonisJS 应用并启动开发服务器。","frontmatter":{"title":"安装","description":"了解如何创建新的 AdonisJS 应用并启动开发服务器。"},"headers":[],"relativePath":"start/installation.md","filePath":"start/installation.md","lastUpdated":1790089116000}'),n={name:"start/installation.md"};function l(p,s,r,h,o,d){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>本指南介绍如何从零开始搭建一个新的 AdonisJS 应用。内容涵盖前置条件、项目创建和启动开发服务器。你不需要事先了解 AdonisJS，但具备基本的 Node.js 知识会很有帮助。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>在开始之前，请确保已安装以下工具。</p><ul><li><strong>Node.js ≥ 24.x</strong></li><li><strong>npm ≥ 11.x</strong></li></ul><p>你可以使用以下命令验证已安装的版本。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>在继续之前，请确认你的 Node.js 和 npm 版本满足这些要求。你可以从 <a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js 官网</a>下载最新版本，或使用 Volta/nvm 等版本管理器。</p><h2 id="创建新应用" tabindex="-1">创建新应用 <a class="header-anchor" href="#创建新应用" aria-label="Permalink to &quot;创建新应用&quot;">​</a></h2><p>AdonisJS 提供了 <code>create-adonisjs</code> 初始化器包来搭建新应用的脚手架。该包会根据你在设置过程中的选择，创建一个包含所有必要文件、依赖和配置的新项目目录。</p><p>将 <code>[project-name]</code> 替换为你想要的项目名称。初始化器会创建一个以该名称命名的新目录，并在其中设置好你的 AdonisJS 应用。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adonisjs@latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [project-name]</span></span></code></pre></div><p>该命令会启动交互式设置并询问你选择启动套件，你也可以通过 <code>--kit</code> CLI 选项预先指定启动套件。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adonisjs@latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [project-name] -- --kit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hypermedia</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adonisjs@latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [project-name] -- --kit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">react</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adonisjs@latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [project-name] -- --kit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vue</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adonisjs@latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [project-name] -- --kit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">api</span></span></code></pre></div><h3 id="官方启动套件" tabindex="-1">官方启动套件 <a class="header-anchor" href="#官方启动套件" aria-label="Permalink to &quot;官方启动套件&quot;">​</a></h3><p>AdonisJS 提供四个官方启动套件。每个套件根据你希望如何构建用户界面和管理交互性，设置不同类型的应用。</p><ul><li><p><a href="https://github.com/adonisjs/starter-kits/tree/main/hypermedia" target="_blank" rel="noreferrer"><strong>超媒体启动套件</strong></a>。使用 Edge 作为服务端模板引擎，并集成 Alpine.js 为前端添加轻量级的响应式行为。适合主要在服务器上渲染 HTML、只需要极少前端逻辑的应用。</p></li><li><p><a href="https://github.com/adonisjs/starter-kits/tree/main/inertia-react" target="_blank" rel="noreferrer"><strong>React 启动套件</strong></a>。使用 Inertia.js 搭配 React 构建由 AdonisJS 后端驱动的全栈 React 应用。根据你的配置，它既可以作为服务端渲染应用运行，也可以作为单页应用（SPA）运行。</p></li><li><p><a href="https://github.com/adonisjs/starter-kits/tree/main/inertia-vue" target="_blank" rel="noreferrer"><strong>Vue 启动套件</strong></a>。与 React 设置类似，但以 Vue 作为前端框架。它利用 Inertia.js 并提供相同的全栈能力，包括后端驱动的路由、共享状态和 SPA 支持。</p></li><li><p><a href="https://github.com/adonisjs/starter-kits/tree/main/api" target="_blank" rel="noreferrer"><strong>API 启动套件</strong></a>。一个包含两个应用的单体仓库设置：一个 AdonisJS 后端和一个空白前端项目，你可以在其中配置任何前端框架（TanStack Start、Nuxt、Next.js 或其他）。后端和前端之间已经配置好了端到端类型安全和共享的转换器类型。</p></li></ul><p>所有启动套件都预先配置了合理的默认值、精简的开发工作流和开箱即用的身份认证功能。详细的对比和使用指南，请参阅<a href="./pick_your_path.html">选择你的路径</a>指南。</p><h3 id="社区启动套件" tabindex="-1">社区启动套件 <a class="header-anchor" href="#社区启动套件" aria-label="Permalink to &quot;社区启动套件&quot;">​</a></h3><p>除了官方套件外，AdonisJS 社区也维护针对特定用例的启动套件。</p><ul><li><p><a href="https://github.com/batosai/adonisjs-slim-starter-kit" target="_blank" rel="noreferrer"><strong>Slim 启动套件</strong></a>。一个极简的 AdonisJS v7 设置，包含框架核心和 Japa 测试运行器，专为希望从轻量级基础开始的团队设计。</p></li><li><p><a href="https://github.com/batosai/adonisjs-mcp-starter-kit" target="_blank" rel="noreferrer"><strong>MCP 启动套件</strong></a>。一个极简的 AdonisJS v7 设置，内置 MCP 支持，适用于你想在应用中暴露 MCP 工具、资源和提示的场景。</p></li></ul><h2 id="项目默认配置" tabindex="-1">项目默认配置 <a class="header-anchor" href="#项目默认配置" aria-label="Permalink to &quot;项目默认配置&quot;">​</a></h2><p>每个新建的 AdonisJS 应用都包含：</p><ul><li>预设的目录结构。</li><li>配置了 <strong>SQLite</strong> 作为默认数据库的 <a href="https://lucid.adonisjs.com" target="_blank" rel="noreferrer">Lucid ORM</a>。</li><li>用于登录和注册的内置<strong>身份认证</strong>流程。</li><li>预定义配置的 <strong>ESLint</strong> 和 <strong>Prettier</strong> 设置。</li></ul><p>这些功能帮助你快速上手。你可以随着项目发展自定义、扩展或移除它们。</p><h2 id="启动开发服务器" tabindex="-1">启动开发服务器 <a class="header-anchor" href="#启动开发服务器" aria-label="Permalink to &quot;启动开发服务器&quot;">​</a></h2><p>创建应用后，进入项目目录并启动开发服务器。</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-hepHJ" id="tab-ZC63UwK" checked><label data-title="Hypermedia / Inertia 套件" for="tab-ZC63UwK">Hypermedia / Inertia 套件</label><input type="radio" name="group-hepHJ" id="tab-8KBV48x"><label data-title="API 套件" for="tab-8KBV48x">API 套件</label></div><div class="blocks"><div class="language-sh vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hmr</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></div></div><p><strong>对于 Hypermedia / Inertia 套件</strong>：服务器运行后，打开浏览器访问 <a href="http://localhost:3333" target="_blank" rel="noreferrer">http://localhost:3333</a>。你应该会看到 AdonisJS 欢迎页面，确认安装成功。</p><p><strong>对于 API 套件</strong>：API 启动套件是由 <a href="https://turbo.build/repo" target="_blank" rel="noreferrer">Turborepo</a> 管理的单体仓库。从项目根目录启动所有应用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>这会同时启动后端（AdonisJS）和前端的开发服务器。后端运行在 <a href="http://localhost:3333" target="_blank" rel="noreferrer">http://localhost:3333</a>，并返回一个 JSON 响应：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;world&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="你刚刚安装了什么" tabindex="-1">你刚刚安装了什么 <a class="header-anchor" href="#你刚刚安装了什么" aria-label="Permalink to &quot;你刚刚安装了什么&quot;">​</a></h2><p>你的启动套件包含：</p><ul><li><p><strong>预配置的开发环境</strong>。TypeScript、ESLint、Prettier 和 Vite 都已用合理的默认值设置好。</p></li><li><p><strong>数据库设置</strong>。Lucid ORM 已配置 SQLite，随时可以开始构建模型和运行迁移。</p></li><li><p><strong>有条理的项目结构</strong>。路由定义在 <code>start/routes.ts</code>，模型位于 <code>app/models/</code>，控制器位于 <code>app/controllers/</code>，中间件位于 <code>app/middleware/</code>。这种约定让代码库在增长时保持条理。</p></li><li><p><strong>可用的身份认证</strong>。所有启动套件都包含功能完整的身份认证系统，带有注册和登录流程。</p></li></ul><div class="tip custom-block"><p class="custom-block-title">对于 Hypermedia / Inertia 套件</p><p>尝试在 <a href="http://localhost:3333/signup" target="_blank" rel="noreferrer">http://localhost:3333/signup</a> 创建账户，并在 <a href="http://localhost:3333/login" target="_blank" rel="noreferrer">http://localhost:3333/login</a> 登录。<code>users</code> 表已存在于你的 SQLite 数据库（<code>tmp/db.sqlite</code>）中。</p></div><div class="tip custom-block"><p class="custom-block-title">对于 API 套件</p><p>身份认证端点位于 <code>POST /api/v1/auth/signup</code> 和 <code>POST /api/v1/auth/login</code>。你可以用任何 HTTP 客户端（curl、Postman 或你的前端应用）测试它们。<code>users</code> 表已存在于你的 SQLite 数据库（<code>apps/backend/tmp/db.sqlite</code>）中。</p></div><h3 id="开发服务器模式" tabindex="-1">开发服务器模式 <a class="header-anchor" href="#开发服务器模式" aria-label="Permalink to &quot;开发服务器模式&quot;">​</a></h3><ul><li><p><strong>热模块替换（--hmr）</strong>。这是大多数开发场景的推荐方式。HMR 在浏览器中更新你的应用而无需完整页面刷新，在即时反映代码更改的同时保留应用状态。这提供了最快的开发反馈循环，特别是在处理前端组件或样式时。</p></li><li><p><strong>文件监听（--watch）</strong>。此模式会在你更改代码时自动重启整个服务器进程。虽然由于需要完整重启，这种方式比 HMR 稍慢，但它确保每次更改后应用状态都是干净的，在处理服务端逻辑或 HMR 更新不够用时很有帮助。</p></li></ul><h2 id="探索其他命令" tabindex="-1">探索其他命令 <a class="header-anchor" href="#探索其他命令" aria-label="Permalink to &quot;探索其他命令&quot;">​</a></h2><p><code>ace</code> 命令行工具包含许多用于开发和生产工作流的命令。</p><p>要查看所有可用命令，请运行以下命令。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ace</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><strong>初次使用 AdonisJS？</strong> 按照<a href="./tutorial/hypermedia/overview.html">教程</a>构建一个完整的应用，了解各部分如何协同工作。</li><li><strong>想先了解代码库？</strong> 阅读<a href="./folder_structure.html">目录结构</a>了解项目的组织方式。</li></ul>`,49)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
